insert into auth.users (id, email, aud, role) values ('00000000-0000-4000-8000-000000000001', 'team@orbis.invalid', 'authenticated', 'authenticated') on conflict (id) do nothing;
insert into public.destinations (id, name, country, region, lat, lng, hidden_gem, popularity, styles, tagline, description, best_time, scene) values ('kyoto', 'Kyoto', 'Japan', 'Kansai', 35.01, 135.77, false, 92, array['culture', 'photography', 'food', 'wellness']::text[], 'Temples, bamboo groves & autumn maple', 'Over 1,600 temples, tea houses in the Higashiyama hills and lantern-lit Gion lanes. Go early and go north to escape the crowds.', 'Late Oct – Nov', '{"kind":"temple","palette":["#F7C59F","#F2E6D8","#B44A2C","#3D2B25"]}'::jsonb) on conflict (id) do update set name = excluded.name, country = excluded.country, region = excluded.region, lat = excluded.lat, lng = excluded.lng, hidden_gem = excluded.hidden_gem, popularity = excluded.popularity, styles = excluded.styles, tagline = excluded.tagline, description = excluded.description, best_time = excluded.best_time, scene = excluded.scene;
insert into public.destinations (id, name, country, region, lat, lng, hidden_gem, popularity, styles, tagline, description, best_time, scene) values ('tokyo', 'Tokyo', 'Japan', 'Kantō', 35.68, 139.69, false, 97, array['tech', 'food', 'nightlife', 'fashion', 'sports']::text[], 'Neon, ramen and infinite neighbourhoods', 'A city of villages: vintage Shimokitazawa, tech-hub Akihabara, quiet Yanaka. The marathon and design weeks pull global crowds.', 'Mar – May, Oct – Nov', '{"kind":"city","palette":["#3B2C5E","#E77F67","#2B2442","#141026"]}'::jsonb) on conflict (id) do update set name = excluded.name, country = excluded.country, region = excluded.region, lat = excluded.lat, lng = excluded.lng, hidden_gem = excluded.hidden_gem, popularity = excluded.popularity, styles = excluded.styles, tagline = excluded.tagline, description = excluded.description, best_time = excluded.best_time, scene = excluded.scene;
insert into public.destinations (id, name, country, region, lat, lng, hidden_gem, popularity, styles, tagline, description, best_time, scene) values ('svaneti', 'Svaneti Valley', 'Georgia', 'Caucasus', 43, 42.73, true, 18, array['adventure', 'culture', 'photography', 'eco']::text[], 'Glacial peaks & 1,000-year-old stone towers', 'Medieval defensive towers stand beneath Ushba and Shkhara. The Mestia–Ushguli trek is four days of glaciers, supras and silence.', 'Jul – Sep', '{"kind":"mountain","palette":["#9FC3E7","#EAF1F7","#6F86A3","#2F3D4F"]}'::jsonb) on conflict (id) do update set name = excluded.name, country = excluded.country, region = excluded.region, lat = excluded.lat, lng = excluded.lng, hidden_gem = excluded.hidden_gem, popularity = excluded.popularity, styles = excluded.styles, tagline = excluded.tagline, description = excluded.description, best_time = excluded.best_time, scene = excluded.scene;
insert into public.destinations (id, name, country, region, lat, lng, hidden_gem, popularity, styles, tagline, description, best_time, scene) values ('kravice', 'Kravice Waterfalls', 'Bosnia and Herz.', 'Herzegovina', 43.16, 17.61, true, 22, array['eco', 'vacation', 'photography']::text[], 'Emerald pools & undiscovered wild freshwater', 'A 25-metre amphitheatre of tufa cascades on the Trebižat river. Swim, kayak, then eat fresh trout at a riverside mill.', 'May – Jun, Sep', '{"kind":"water","palette":["#A8D8C8","#EAF6EF","#3E8E6D","#1F4D3B"]}'::jsonb) on conflict (id) do update set name = excluded.name, country = excluded.country, region = excluded.region, lat = excluded.lat, lng = excluded.lng, hidden_gem = excluded.hidden_gem, popularity = excluded.popularity, styles = excluded.styles, tagline = excluded.tagline, description = excluded.description, best_time = excluded.best_time, scene = excluded.scene;
insert into public.destinations (id, name, country, region, lat, lng, hidden_gem, popularity, styles, tagline, description, best_time, scene) values ('albarracin', 'Albarracín', 'Spain', 'Aragón', 40.41, -1.44, true, 20, array['culture', 'photography', 'adventure']::text[], 'A medieval pink town nestled in a river gorge', 'Rose-coloured houses tumble down a canyon wrapped by Moorish walls. Pine forests nearby hide prehistoric rock art and bouldering.', 'Apr – Jun, Sep – Oct', '{"kind":"desert","palette":["#F5B998","#FBE9DC","#C0705A","#6B3A2E"]}'::jsonb) on conflict (id) do update set name = excluded.name, country = excluded.country, region = excluded.region, lat = excluded.lat, lng = excluded.lng, hidden_gem = excluded.hidden_gem, popularity = excluded.popularity, styles = excluded.styles, tagline = excluded.tagline, description = excluded.description, best_time = excluded.best_time, scene = excluded.scene;
insert into public.destinations (id, name, country, region, lat, lng, hidden_gem, popularity, styles, tagline, description, best_time, scene) values ('lofoten', 'Lofoten', 'Norway', 'Nordland', 68.2, 13.6, true, 38, array['adventure', 'photography', 'eco']::text[], 'Arctic peaks rising straight out of the sea', 'Red rorbu cabins, surfable Arctic beaches at Unstad and the northern lights from September.', 'Jun – Aug, Sep – Mar for aurora', '{"kind":"mountain","palette":["#2E3F66","#9DB6D8","#3A4F6E","#18233A"]}'::jsonb) on conflict (id) do update set name = excluded.name, country = excluded.country, region = excluded.region, lat = excluded.lat, lng = excluded.lng, hidden_gem = excluded.hidden_gem, popularity = excluded.popularity, styles = excluded.styles, tagline = excluded.tagline, description = excluded.description, best_time = excluded.best_time, scene = excluded.scene;
insert into public.destinations (id, name, country, region, lat, lng, hidden_gem, popularity, styles, tagline, description, best_time, scene) values ('lisbon', 'Lisbon', 'Portugal', 'Estremadura', 38.72, -9.14, false, 85, array['tech', 'food', 'nightlife', 'vacation']::text[], 'Tiled hills, fado & a booming founder scene', 'Home of Web Summit, sunset miradouros and pastel de nata. Surf Ericeira or Costa da Caparica in under an hour.', 'Apr – Jun, Sep – Oct', '{"kind":"coast","palette":["#F6C28B","#FCEBD5","#D9886A","#5A6B8C"]}'::jsonb) on conflict (id) do update set name = excluded.name, country = excluded.country, region = excluded.region, lat = excluded.lat, lng = excluded.lng, hidden_gem = excluded.hidden_gem, popularity = excluded.popularity, styles = excluded.styles, tagline = excluded.tagline, description = excluded.description, best_time = excluded.best_time, scene = excluded.scene;
insert into public.destinations (id, name, country, region, lat, lng, hidden_gem, popularity, styles, tagline, description, best_time, scene) values ('milan', 'Milan', 'Italy', 'Lombardy', 45.46, 9.19, false, 80, array['fashion', 'food', 'culture', 'events']::text[], 'Design week, aperitivo and the Duomo rooftops', 'Global capital of fashion and furniture design. Navigli canals come alive at aperitivo hour.', 'Apr (Design Week), Sep (Fashion Week)', '{"kind":"city","palette":["#E9B9A0","#F7E7DC","#9C6B5A","#3E2C2A"]}'::jsonb) on conflict (id) do update set name = excluded.name, country = excluded.country, region = excluded.region, lat = excluded.lat, lng = excluded.lng, hidden_gem = excluded.hidden_gem, popularity = excluded.popularity, styles = excluded.styles, tagline = excluded.tagline, description = excluded.description, best_time = excluded.best_time, scene = excluded.scene;
insert into public.destinations (id, name, country, region, lat, lng, hidden_gem, popularity, styles, tagline, description, best_time, scene) values ('patagonia', 'Torres del Paine', 'Chile', 'Patagonia', -50.94, -73.4, false, 55, array['adventure', 'eco', 'photography']::text[], 'Granite towers, glaciers and the W-Trek', 'Five days of turquoise lakes, hanging glaciers and wind you''ll never forget.', 'Nov – Mar', '{"kind":"mountain","palette":["#8FB7D9","#E5EEF5","#56708C","#2A3A2E"]}'::jsonb) on conflict (id) do update set name = excluded.name, country = excluded.country, region = excluded.region, lat = excluded.lat, lng = excluded.lng, hidden_gem = excluded.hidden_gem, popularity = excluded.popularity, styles = excluded.styles, tagline = excluded.tagline, description = excluded.description, best_time = excluded.best_time, scene = excluded.scene;
insert into public.destinations (id, name, country, region, lat, lng, hidden_gem, popularity, styles, tagline, description, best_time, scene) values ('ohrid', 'Lake Ohrid', 'Macedonia', 'Southwest', 41.11, 20.8, true, 24, array['culture', 'vacation', 'wellness']::text[], 'One of Europe''s oldest lakes & cliffside chapels', 'Byzantine churches, Ottoman lanes and swimming coves without the Adriatic crowds.', 'Jun – Sep', '{"kind":"water","palette":["#9CC9E2","#EAF3F8","#4E7FA0","#2C3E50"]}'::jsonb) on conflict (id) do update set name = excluded.name, country = excluded.country, region = excluded.region, lat = excluded.lat, lng = excluded.lng, hidden_gem = excluded.hidden_gem, popularity = excluded.popularity, styles = excluded.styles, tagline = excluded.tagline, description = excluded.description, best_time = excluded.best_time, scene = excluded.scene;
insert into public.destinations (id, name, country, region, lat, lng, hidden_gem, popularity, styles, tagline, description, best_time, scene) values ('gjirokaster', 'Gjirokastër', 'Albania', 'Southern Albania', 40.08, 20.14, true, 16, array['culture', 'photography', 'food']::text[], 'The stone city of a thousand steps', 'UNESCO Ottoman tower-houses with slate roofs, a hilltop castle and slow-cooked qifqi.', 'May – Jun, Sep – Oct', '{"kind":"temple","palette":["#D6C3A5","#F3ECE1","#8C7A62","#3E3528"]}'::jsonb) on conflict (id) do update set name = excluded.name, country = excluded.country, region = excluded.region, lat = excluded.lat, lng = excluded.lng, hidden_gem = excluded.hidden_gem, popularity = excluded.popularity, styles = excluded.styles, tagline = excluded.tagline, description = excluded.description, best_time = excluded.best_time, scene = excluded.scene;
insert into public.destinations (id, name, country, region, lat, lng, hidden_gem, popularity, styles, tagline, description, best_time, scene) values ('oaxaca', 'Oaxaca', 'Mexico', 'Oaxaca', 17.07, -96.73, true, 45, array['food', 'culture', 'events']::text[], 'Seven moles, mezcal and Día de Muertos', 'Markets, Zapotec ruins at Monte Albán and the most moving Día de Muertos celebrations in Mexico.', 'Oct – Nov, Jul (Guelaguetza)', '{"kind":"desert","palette":["#F59E6B","#FCE2C9","#B5543A","#4E2A23"]}'::jsonb) on conflict (id) do update set name = excluded.name, country = excluded.country, region = excluded.region, lat = excluded.lat, lng = excluded.lng, hidden_gem = excluded.hidden_gem, popularity = excluded.popularity, styles = excluded.styles, tagline = excluded.tagline, description = excluded.description, best_time = excluded.best_time, scene = excluded.scene;
insert into public.destinations (id, name, country, region, lat, lng, hidden_gem, popularity, styles, tagline, description, best_time, scene) values ('faroe', 'Faroe Islands', 'Faroe Islands', 'North Atlantic', 62, -6.79, true, 21, array['adventure', 'photography', 'eco']::text[], 'Sea cliffs, grass roofs & 70,000 sheep', 'Eighteen volcanic islands linked by sub-sea tunnels. Múlafossur and Trælanípa are unreal in person.', 'May – Aug', '{"kind":"coast","palette":["#B6C7CF","#E9EEF0","#5F7A6A","#2D3B33"]}'::jsonb) on conflict (id) do update set name = excluded.name, country = excluded.country, region = excluded.region, lat = excluded.lat, lng = excluded.lng, hidden_gem = excluded.hidden_gem, popularity = excluded.popularity, styles = excluded.styles, tagline = excluded.tagline, description = excluded.description, best_time = excluded.best_time, scene = excluded.scene;
insert into public.destinations (id, name, country, region, lat, lng, hidden_gem, popularity, styles, tagline, description, best_time, scene) values ('hoian', 'Hội An', 'Vietnam', 'Quảng Nam', 15.88, 108.33, false, 70, array['culture', 'food', 'vacation', 'photography']::text[], 'Lantern-lit old town & riverside tailors', 'Ochre merchant houses, cao lầu noodles and 24-hour custom tailoring.', 'Feb – Apr', '{"kind":"water","palette":["#F6B26B","#FBE3C4","#C4683A","#3B2A1E"]}'::jsonb) on conflict (id) do update set name = excluded.name, country = excluded.country, region = excluded.region, lat = excluded.lat, lng = excluded.lng, hidden_gem = excluded.hidden_gem, popularity = excluded.popularity, styles = excluded.styles, tagline = excluded.tagline, description = excluded.description, best_time = excluded.best_time, scene = excluded.scene;
insert into public.destinations (id, name, country, region, lat, lng, hidden_gem, popularity, styles, tagline, description, best_time, scene) values ('capetown', 'Cape Town', 'South Africa', 'Western Cape', -33.92, 18.42, false, 78, array['adventure', 'food', 'vacation', 'sports']::text[], 'Table Mountain, wine valleys & penguins', 'Hike Lion''s Head at full moon, sip Stellenbosch Chenin and surf Muizenberg.', 'Nov – Mar', '{"kind":"mountain","palette":["#F4A88A","#FBE4D6","#6E7F8E","#2A3540"]}'::jsonb) on conflict (id) do update set name = excluded.name, country = excluded.country, region = excluded.region, lat = excluded.lat, lng = excluded.lng, hidden_gem = excluded.hidden_gem, popularity = excluded.popularity, styles = excluded.styles, tagline = excluded.tagline, description = excluded.description, best_time = excluded.best_time, scene = excluded.scene;
