insert into public.destinations (id, name, country, region, lat, lng, hidden_gem, popularity, styles, tagline, description, best_time, scene) values ('socotra', 'Socotra', 'Yemen', 'Arabian Sea', 12.46, 53.82, true, 6, array['adventure', 'eco', 'photography']::text[], 'Dragon''s blood trees on an alien island', 'A third of its plants exist nowhere else on Earth. Access only via licensed operators.', 'Oct – Apr', '{"kind":"desert","palette":["#F2C48D","#FBEBD5","#8D6E4C","#3F2F22"]}'::jsonb) on conflict (id) do update set name = excluded.name, country = excluded.country, region = excluded.region, lat = excluded.lat, lng = excluded.lng, hidden_gem = excluded.hidden_gem, popularity = excluded.popularity, styles = excluded.styles, tagline = excluded.tagline, description = excluded.description, best_time = excluded.best_time, scene = excluded.scene;
insert into public.destinations (id, name, country, region, lat, lng, hidden_gem, popularity, styles, tagline, description, best_time, scene) values ('luangprabang', 'Luang Prabang', 'Laos', 'Northern Laos', 19.89, 102.13, true, 40, array['culture', 'wellness', 'eco']::text[], 'Saffron-robed dawn alms & Kuang Si falls', 'Gilded wats on a Mekong peninsula, night markets and turquoise jungle cascades.', 'Nov – Feb', '{"kind":"forest","palette":["#F5C38B","#FBEAD3","#5E8C5A","#24402A"]}'::jsonb) on conflict (id) do update set name = excluded.name, country = excluded.country, region = excluded.region, lat = excluded.lat, lng = excluded.lng, hidden_gem = excluded.hidden_gem, popularity = excluded.popularity, styles = excluded.styles, tagline = excluded.tagline, description = excluded.description, best_time = excluded.best_time, scene = excluded.scene;
insert into public.destinations (id, name, country, region, lat, lng, hidden_gem, popularity, styles, tagline, description, best_time, scene) values ('melbourne', 'Melbourne', 'Australia', 'Victoria', -37.81, 144.96, false, 75, array['sports', 'food', 'events', 'fashion']::text[], 'Laneway coffee & the Australian Open', 'Grand Slam tennis, the Grand Prix and the best flat white of your life.', 'Jan (AO), Mar – May', '{"kind":"city","palette":["#A7C7E7","#EAF2FA","#5C6F86","#22303F"]}'::jsonb) on conflict (id) do update set name = excluded.name, country = excluded.country, region = excluded.region, lat = excluded.lat, lng = excluded.lng, hidden_gem = excluded.hidden_gem, popularity = excluded.popularity, styles = excluded.styles, tagline = excluded.tagline, description = excluded.description, best_time = excluded.best_time, scene = excluded.scene;
insert into public.destinations (id, name, country, region, lat, lng, hidden_gem, popularity, styles, tagline, description, best_time, scene) values ('matera', 'Matera', 'Italy', 'Basilicata', 40.67, 16.6, true, 35, array['culture', 'photography', 'food']::text[], 'Cave dwellings carved into a ravine', 'The Sassi, inhabited for 9,000 years, glow gold at dusk. Sleep in a cave hotel.', 'Apr – Jun, Sep – Oct', '{"kind":"desert","palette":["#E8B88A","#F8E8D6","#A27A55","#4A3826"]}'::jsonb) on conflict (id) do update set name = excluded.name, country = excluded.country, region = excluded.region, lat = excluded.lat, lng = excluded.lng, hidden_gem = excluded.hidden_gem, popularity = excluded.popularity, styles = excluded.styles, tagline = excluded.tagline, description = excluded.description, best_time = excluded.best_time, scene = excluded.scene;
insert into public.destinations (id, name, country, region, lat, lng, hidden_gem, popularity, styles, tagline, description, best_time, scene) values ('reykjavik', 'Reykjavík', 'Iceland', 'Capital Region', 64.15, -21.94, false, 68, array['adventure', 'wellness', 'events', 'photography']::text[], 'Geothermal pools & the midnight sun', 'Base for the Golden Circle, Iceland Airwaves and neighbourhood hot pots.', 'Jun – Aug, Nov for Airwaves', '{"kind":"mountain","palette":["#2F3E5C","#7FA3C9","#3E5C6E","#1A2733"]}'::jsonb) on conflict (id) do update set name = excluded.name, country = excluded.country, region = excluded.region, lat = excluded.lat, lng = excluded.lng, hidden_gem = excluded.hidden_gem, popularity = excluded.popularity, styles = excluded.styles, tagline = excluded.tagline, description = excluded.description, best_time = excluded.best_time, scene = excluded.scene;
insert into public.destinations (id, name, country, region, lat, lng, hidden_gem, popularity, styles, tagline, description, best_time, scene) values ('marrakech', 'Marrakech', 'Morocco', 'Marrakesh-Safi', 31.63, -8, false, 77, array['culture', 'food', 'fashion', 'wellness']::text[], 'Souks, riads & Atlas day trips', 'Jemaa el-Fnaa at dusk, hammams, and the Majorelle garden''s electric blue.', 'Mar – May, Oct – Nov', '{"kind":"desert","palette":["#F7A072","#FCE0CB","#C0583A","#5A2A1F"]}'::jsonb) on conflict (id) do update set name = excluded.name, country = excluded.country, region = excluded.region, lat = excluded.lat, lng = excluded.lng, hidden_gem = excluded.hidden_gem, popularity = excluded.popularity, styles = excluded.styles, tagline = excluded.tagline, description = excluded.description, best_time = excluded.best_time, scene = excluded.scene;
insert into public.gems (author_id, destination_id, name, description, tip, category, styles, lat, lng, country) select '00000000-0000-4000-8000-000000000001', 'kyoto', 'Otagi Nenbutsu-ji', 'A hillside temple above Arashiyama where 1,200 moss-covered stone rakan statues each wear a different expression.', 'Walk up from Saga-Toriimoto after the bamboo grove. The steps get slick with morning dew, so wear shoes with grip.', 'culture', array['culture', 'photography']::text[], 35.0275, 135.6627, 'Japan' where not exists (select 1 from public.gems where author_id = '00000000-0000-4000-8000-000000000001' and name = 'Otagi Nenbutsu-ji');
insert into public.gems (author_id, destination_id, name, description, tip, category, styles, lat, lng, country) select '00000000-0000-4000-8000-000000000001', 'kyoto', 'Saga-Toriimoto Preserved Street', 'A quiet lane of thatched machiya houses north of the bamboo grove that most day-trippers never reach.', 'Take the northern path out of the bamboo grove and keep walking. Early morning is almost empty.', 'culture', array['culture', 'photography']::text[], 35.0265, 135.668, 'Japan' where not exists (select 1 from public.gems where author_id = '00000000-0000-4000-8000-000000000001' and name = 'Saga-Toriimoto Preserved Street');
insert into public.gems (author_id, destination_id, name, description, tip, category, styles, lat, lng, country) select '00000000-0000-4000-8000-000000000001', 'kyoto', 'Kibune Shrine', 'A mountain shrine in a cedar valley, reached by the Kurama–Kibune ridge trail. Lantern-lined steps glow at dusk.', 'Hike over from Kurama in about 90 minutes, then eat lunch on a platform built over the river.', 'nature', array['culture', 'eco', 'wellness']::text[], 35.1218, 135.7625, 'Japan' where not exists (select 1 from public.gems where author_id = '00000000-0000-4000-8000-000000000001' and name = 'Kibune Shrine');
insert into public.gems (author_id, destination_id, name, description, tip, category, styles, lat, lng, country) select '00000000-0000-4000-8000-000000000001', 'tokyo', 'Yanaka Ginza', 'An old-Tokyo shopping street of croquette stands, sweet shops and cats, spared from wartime bombing.', 'Come at dusk and start from the ''Yuyake Dandan'' steps at the top for the sunset view.', 'food', array['food', 'culture']::text[], 35.7277, 139.766, 'Japan' where not exists (select 1 from public.gems where author_id = '00000000-0000-4000-8000-000000000001' and name = 'Yanaka Ginza');
insert into public.gems (author_id, destination_id, name, description, tip, category, styles, lat, lng, country) select '00000000-0000-4000-8000-000000000001', 'tokyo', 'Gotokuji Temple', 'The temple said to be the birthplace of the maneki-neko, with thousands of beckoning-cat figurines.', 'Ride the little Setagaya tram line to get here. It''s a sight in itself.', 'culture', array['culture', 'photography']::text[], 35.6489, 139.6473, 'Japan' where not exists (select 1 from public.gems where author_id = '00000000-0000-4000-8000-000000000001' and name = 'Gotokuji Temple');
insert into public.gems (author_id, destination_id, name, description, tip, category, styles, lat, lng, country) select '00000000-0000-4000-8000-000000000001', 'lisbon', 'Miradouro da Senhora do Monte', 'Lisbon''s highest viewpoint, looking over the castle, the Baixa and the river.', 'Skip Tram 28 and walk up through Graça. Bring a bottle of vinho verde for sunset.', 'viewpoint', array['photography', 'vacation']::text[], 38.7192, -9.1328, 'Portugal' where not exists (select 1 from public.gems where author_id = '00000000-0000-4000-8000-000000000001' and name = 'Miradouro da Senhora do Monte');
insert into public.gems (author_id, destination_id, name, description, tip, category, styles, lat, lng, country) select '00000000-0000-4000-8000-000000000001', 'lisbon', 'Jardim do Torel', 'A small terraced garden with a city view, deck chairs and, in summer, a pop-up pool and bar.', 'Take the Elevador do Lavra funicular from Restauradores and you''ll arrive at the gate.', 'viewpoint', array['vacation', 'wellness']::text[], 38.7183, -9.1426, 'Portugal' where not exists (select 1 from public.gems where author_id = '00000000-0000-4000-8000-000000000001' and name = 'Jardim do Torel');
insert into public.gems (author_id, destination_id, name, description, tip, category, styles, lat, lng, country) select '00000000-0000-4000-8000-000000000001', 'svaneti', 'Ushguli', 'One of Europe''s highest inhabited villages, with medieval Svan towers beneath Shkhara glacier.', 'There are no ATMs after Mestia. Bring cash in lari for guesthouses.', 'culture', array['adventure', 'culture', 'photography']::text[], 42.9167, 43.0167, 'Georgia' where not exists (select 1 from public.gems where author_id = '00000000-0000-4000-8000-000000000001' and name = 'Ushguli');
insert into public.gems (author_id, destination_id, name, description, tip, category, styles, lat, lng, country) select '00000000-0000-4000-8000-000000000001', 'kravice', 'Počitelj Old Town', 'A walled Ottoman-era village climbing a hillside over the Neretva river, 15 minutes from Kravice.', 'Climb the tower at the top before 10 AM, then swim at Kravice in the afternoon.', 'culture', array['culture', 'photography']::text[], 43.1347, 17.7311, 'Bosnia and Herz.' where not exists (select 1 from public.gems where author_id = '00000000-0000-4000-8000-000000000001' and name = 'Počitelj Old Town');
insert into public.gems (author_id, destination_id, name, description, tip, category, styles, lat, lng, country) select '00000000-0000-4000-8000-000000000001', 'albarracin', 'Pinares de Rodeno Rock Art', 'Red sandstone outcrops in a pine forest, with prehistoric rock paintings and bouldering.', 'Pick up a free trail map at the Dornaque visitor centre.', 'nature', array['adventure', 'culture', 'eco']::text[], 40.4, -1.37, 'Spain' where not exists (select 1 from public.gems where author_id = '00000000-0000-4000-8000-000000000001' and name = 'Pinares de Rodeno Rock Art');
insert into public.gems (author_id, destination_id, name, description, tip, category, styles, lat, lng, country) select '00000000-0000-4000-8000-000000000001', 'lofoten', 'Kvalvika Beach', 'A white-sand Arctic beach enclosed by mountains, reached only on foot.', 'Hike up Ryten for the view straight down onto the beach, and skip the Reinebringen crowds.', 'beach', array['adventure', 'photography']::text[], 68.0762, 13.0256, 'Norway' where not exists (select 1 from public.gems where author_id = '00000000-0000-4000-8000-000000000001' and name = 'Kvalvika Beach');
insert into public.gems (author_id, destination_id, name, description, tip, category, styles, lat, lng, country) select '00000000-0000-4000-8000-000000000001', 'matera', 'Belvedere di Murgia Timone', 'The viewpoint across the Gravina gorge where the cave city of Matera lights up at dusk.', 'Cross the hanging bridge from the Sassi; it''s about a 40-minute walk.', 'viewpoint', array['photography', 'culture']::text[], 40.6667, 16.6219, 'Italy' where not exists (select 1 from public.gems where author_id = '00000000-0000-4000-8000-000000000001' and name = 'Belvedere di Murgia Timone');
insert into public.gems (author_id, destination_id, name, description, tip, category, styles, lat, lng, country) select '00000000-0000-4000-8000-000000000001', 'oaxaca', 'Hierve el Agua', 'Mineral springs that formed petrified ''waterfalls'' on a cliff edge, with natural infinity pools.', 'Go on a weekday morning and combine it with a mezcal palenque in Santiago Matatlán.', 'nature', array['adventure', 'eco', 'photography']::text[], 16.8656, -96.2761, 'Mexico' where not exists (select 1 from public.gems where author_id = '00000000-0000-4000-8000-000000000001' and name = 'Hierve el Agua');
insert into public.gems (author_id, destination_id, name, description, tip, category, styles, lat, lng, country) select '00000000-0000-4000-8000-000000000001', 'faroe', 'Múlafossur Waterfall', 'A waterfall dropping straight from the cliffs of Gásadalur into the Atlantic.', 'Fog lifts fast. Keep a backup hike on the other side of the island.', 'nature', array['adventure', 'photography']::text[], 62.1105, -7.4352, 'Faroe Islands' where not exists (select 1 from public.gems where author_id = '00000000-0000-4000-8000-000000000001' and name = 'Múlafossur Waterfall');
insert into public.gems (author_id, destination_id, name, description, tip, category, styles, lat, lng, country) select '00000000-0000-4000-8000-000000000001', 'hoian', 'An Bàng Beach', 'A relaxed beach with seafood shacks, reached through rice paddies from Hội An.', 'Cycle out at sunrise; the paddy road is cooler and empty.', 'beach', array['vacation', 'food']::text[], 15.9136, 108.3415, 'Vietnam' where not exists (select 1 from public.gems where author_id = '00000000-0000-4000-8000-000000000001' and name = 'An Bàng Beach');
insert into public.gems (author_id, destination_id, name, description, tip, category, styles, lat, lng, country) select '00000000-0000-4000-8000-000000000001', 'luangprabang', 'Mount Phousi at Sunrise', 'A hilltop stupa above the old town with views over the Mekong and Nam Khan rivers.', 'Sunset is packed; sunrise is calm. Watch the morning alms silently, from across the street.', 'viewpoint', array['culture', 'photography', 'wellness']::text[], 19.8913, 102.1386, 'Laos' where not exists (select 1 from public.gems where author_id = '00000000-0000-4000-8000-000000000001' and name = 'Mount Phousi at Sunrise');
insert into public.gems (author_id, destination_id, name, description, tip, category, styles, lat, lng, country) select '00000000-0000-4000-8000-000000000001', 'reykjavik', 'Grótta Lighthouse', 'A lighthouse on a tidal islet at the edge of Reykjavík, with a tiny geothermal foot bath.', 'One of the best low-light-pollution spots in town for the northern lights. Check the tide before crossing.', 'viewpoint', array['photography', 'wellness']::text[], 64.1641, -22.0213, 'Iceland' where not exists (select 1 from public.gems where author_id = '00000000-0000-4000-8000-000000000001' and name = 'Grótta Lighthouse');
insert into public.gems (author_id, destination_id, name, description, tip, category, styles, lat, lng, country) select '00000000-0000-4000-8000-000000000001', 'capetown', 'Kalk Bay Harbour', 'A working fishing harbour with fish-and-chips spots, tidal pools and seals.', 'Take the coastal train from Muizenberg and sit on the sea side.', 'food', array['food', 'vacation']::text[], -34.1278, 18.4489, 'South Africa' where not exists (select 1 from public.gems where author_id = '00000000-0000-4000-8000-000000000001' and name = 'Kalk Bay Harbour');
insert into public.gems (author_id, destination_id, name, description, tip, category, styles, lat, lng, country) select '00000000-0000-4000-8000-000000000001', 'marrakech', 'Le Jardin Secret', 'A restored riad garden in the medina, quiet even when the souks are at their busiest.', 'Pay the small extra fee for the tower; it has the best rooftop view in the medina.', 'culture', array['culture', 'wellness']::text[], 31.6296, -7.9893, 'Morocco' where not exists (select 1 from public.gems where author_id = '00000000-0000-4000-8000-000000000001' and name = 'Le Jardin Secret');
insert into public.gems (author_id, destination_id, name, description, tip, category, styles, lat, lng, country) select '00000000-0000-4000-8000-000000000001', 'gjirokaster', 'Skenduli House', 'An Ottoman tower-house still owned by the family that built it, with guided tours of its rooms.', 'Tours are given by family members; ask about the hidden room.', 'culture', array['culture', 'photography']::text[], 40.0745, 20.14, 'Albania' where not exists (select 1 from public.gems where author_id = '00000000-0000-4000-8000-000000000001' and name = 'Skenduli House');
insert into public.gems (author_id, destination_id, name, description, tip, category, styles, lat, lng, country) select '00000000-0000-4000-8000-000000000001', 'ohrid', 'Church of St. John at Kaneo', 'A 13th-century church on a cliff above Lake Ohrid.', 'Get there by 7 AM, then take a boat to the springs of St. Naum.', 'viewpoint', array['culture', 'photography']::text[], 41.111, 20.7893, 'Macedonia' where not exists (select 1 from public.gems where author_id = '00000000-0000-4000-8000-000000000001' and name = 'Church of St. John at Kaneo');
